/* The old Bootstrap 3 workaround forced body.modal-open to scroll. On touch
   devices that scrolls the page behind the modal, so the footer (Save button)
   of a tall modal could never be reached. Let Bootstrap 4 handle it: the
   .modal itself is the scroll container. */
.modal {
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
}

